def generate(num_rows):
    def factorial(x):
        result = 1
        for i in range(2, x + 1):
            result *= i               # multiply up to x to get x factorial
        return result

    def binomial(row, col):
        return factorial(row) // (factorial(col) * factorial(row - col))  # the nCr formula, from scratch

    triangle = []
    for row in range(num_rows):
        current_row = []
        for col in range(row + 1):
            current_row.append(binomial(row, col))  # every single cell recomputes its own factorials
        triangle.append(current_row)
    return triangle


if __name__ == "__main__":
    num_rows = 5
    for row in generate(num_rows):
        print(row)

