import java.util.*;

public class Main {
    long factorial(int x) {
        long result = 1;
        for (int i = 2; i <= x; i++) {
            result *= i;                     // multiply up to x to get x factorial
        }
        return result;
    }

    int binomial(int row, int col) {
        return (int) (factorial(row) / (factorial(col) * factorial(row - col)));  // the nCr formula, from scratch
    }

    List<List<Integer>> generate(int numRows) {
        List<List<Integer>> triangle = new ArrayList<>();
        for (int row = 0; row < numRows; row++) {
            List<Integer> currentRow = new ArrayList<>();
            for (int col = 0; col <= row; col++) {
                currentRow.add(binomial(row, col));  // every single cell recomputes its own factorials
            }
            triangle.add(currentRow);
        }
        return triangle;
    }

    public static void main(String[] args) {
        int numRows = 5;
        Main solution = new Main();
        for (List<Integer> row : solution.generate(numRows)) {
            System.out.println(row);
        }
    }
}

