#include <bits/stdc++.h>
using namespace std;

long long factorial(int x) {
    long long result = 1;
    for (int i = 2; i <= x; i++) {
        result *= i;                     // multiply up to x to get x factorial
    }
    return result;
}

int binomial(int row, int col) {
    return factorial(row) / (factorial(col) * factorial(row - col));  // the nCr formula, from scratch
}

vector<vector<int>> generate(int numRows) {
    vector<vector<int>> triangle;
    for (int row = 0; row < numRows; row++) {
        vector<int> currentRow;
        for (int col = 0; col <= row; col++) {
            currentRow.push_back(binomial(row, col));  // every single cell recomputes its own factorials
        }
        triangle.push_back(currentRow);
    }
    return triangle;
}

int main() {
    int numRows = 5;
    for (auto& row : generate(numRows)) {
        for (int v : row) {
            cout << v << " ";
        }
        cout << endl;
    }
    return 0;
}

