        List<List<Integer>> triangle = new ArrayList<>();
        for (int row = 0; row < numRows; row++) {
            List<Integer> currentRow = new ArrayList<>(Collections.nCopies(row + 1, 1)); // start filled with 1s
            for (int col = 1; col < row; col++) {
                currentRow.set(col, triangle.get(row - 1).get(col - 1) + triangle.get(row - 1).get(col)); // sum above
            }
            triangle.add(currentRow);
        }
        return triangle;
    }

